  hotel:       { cmv_min:30, cmv_max:38, cmv_alerta:40, perda_toleravel:4, usa_baker:false, usa_overrun:false, usa_pax:true,  usa_fc:true,  unit:'kg'  },
  eventos:     { cmv_min:30, cmv_max:38, cmv_alerta:40, perda_toleravel:5, usa_baker:false, usa_overrun:false, usa_pax:true,  usa_fc:true,  unit:'kg'  },
