};

const sector_config = configs[setor] || configs.restaurante;
return [{ json: { ...item.json, setor, sector_config } }];

const item = items[0];
const raw = item.json.output || item.json.text || '{}';
let decision;
try {
  const clean = raw.replace(/```json\n?/gi,'').replace(/```\n?/g,'').trim();
  decision = JSON.parse(clean);
} catch(e) {
  decision = { agente:'ORACULO', prioridade:'media', parametros:{ setor: item.json.setor||'restaurante', acao:'analise_geral', periodo:'dia' } };
}
return [{ json: { ...item.json, decision, agente: decision.agente, setor: decision.parametros?.setor || item.json.setor || 'restaurante' } }];

options.systemMessage:
Você é o ANALISTA DE INGESTÃO UNIVERSAL do GastroSense AI. Processa qualquer entrada: texto livre, nota fiscal, voz transcrita, planilha.

LÓGICA SETORIAL:
- PADARIA/CONFEITARIA: identificar W da farinha (W170=fraca, W220=média, W300=forte), percentual do padeiro (0.2-2%), tipo de fermento. Salvar metadata: {w_force, baker_percent, fermentation_type}
- BAR: identificar dose padrão em ML (vodka=50ml, cerveja=500ml, destilado=60ml). Salvar metadata: {dose_padrao_ml, teor_alcoolico_pct}
- GELATERIA: bases, overrun_target=40%, maturacao_hours=12. Salvar metadata: {overrun_target_pct, maturation_hours}
- HOTEL/EVENTOS: calcular por PAX. Salvar metadata: {pax_reference, event_type}
- RESTAURANTE: aplicar Fator de Correção (FC = Peso Bruto / Peso Líquido). Salvar metadata: {fator_correcao}

PASSOSs OBRIGATÓRIOS:
1. Extrair itens do texto/documento
2. Para cada item chamar buscar_preco_historico
3. Calcular variação de preço (alerta se > 10%)
4. Chamar salvar_insumo para persistir

SAÍDA JSON:
{
  "action": "upsert_stock_items",
  "registros_processados": 0,
  "itens": [{"name":"","category":"","unit":"","cost_price":0,"supplier":"","quantity_purchased":0,"metadata_setor":{}}],
  "alertas_preco": [{"item":"","preco_anterior":0,"preco_novo":0,"variacao_pct":0}]
}

