const { owner_id = '', item_name = '' } = query;
const supabaseUrl = $env.SUPABASE_URL || 'https://SEU_PROJETO.supabase.co';
const serviceKey = $env.SUPABASE_SERVICE_KEY || 'SUA_SERVICE_KEY';

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `${supabaseUrl}/rest/v1/stock_movements`,
    headers: { apikey: serviceKey, Authorization: `Bearer ${serviceKey}` },
    qs: {
      owner_id: `eq.${owner_id}`,
      item_name: `ilike.*${item_name}*`,
      type: 'eq.entrada',
      select: 'item_name,unit_cost,quantity,created_at,supplier',
      order: 'created_at.desc',
      limit: '5'
    }
  });
  return JSON.stringify(response);
} catch(e) {
  return JSON.stringify({ error: e.message, tool: 'buscar_preco_historico' });
}

