    headers: { apikey: serviceKey, Authorization: `Bearer ${serviceKey}`, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
    body
  });
  return JSON.stringify({ success: true, ordem: recipe_name, quantidade: quantity_portions });
} catch(e) {
  return JSON.stringify({ error: e.message, tool: 'salvar_ordem_producao' });
}

const sale = items[0].json;
const lineItems = sale.line_items || sale.items || sale.receipts?.[0]?.line_items || [];
const receiptDate = sale.receipt_date || sale.created_at || new Date().toISOString();
const ownerId = sale.store_id || sale.merchant_id || sale.owner_id || '';

if (!lineItems.length) return [{ json: { error: 'Sem itens na venda', raw: sale } }];

return lineItems.map(item => ({ json: {
  owner_id: ownerId,
  product_name: item.item_name || item.name || 'Produto',
  product_id_loyverse: item.item_id || item.id || null,
  quantity: parseFloat(item.quantity) || 1,
  unit_price: parseFloat(item.price) || 0,
  total_price: (parseFloat(item.price)||0) * (parseFloat(item.quantity)||1),
  discount_total: parseFloat(item.discount_amount) || 0,
  unit_cost: parseFloat(item.cost) || null,
  created_at: receiptDate,
  source: 'loyverse_webhook',
  receipt_number: sale.receipt_number || sale.id || null
}}));

const item = items[0];
const raw = item.json.output || item.json.text || item.json.data || item.json;
let data;
try {
  data = typeof raw === 'string' ? JSON.parse(raw.replace(/```json\n?/gi,'').replace(/```\n?/g,'').trim()) : raw;
} catch(e) {
  data = { raw_output: raw, parse_error: e.message };
}
return [{ json: {
  success: true,
  timestamp: new Date().toISOString(),
  sistema: 'GastroSense AI',
  versao: '2.0',
  agente: item.json.agente || item.json.decision?.agente || 'desconhecido',
  setor: item.json.setor || 'restaurante',
  owner_id: item.json.owner_id,
  data
} }];
